                                       'Section: Aviation Services Law (Compensation and '
                                       'Assistance for Flight Cancellation or Change in '
                                       'Conditions), 5772-2012 > Section 2 - Conditions for '
                                       'entitlement to benefits > 2(a)\n'
                                       'Provision ID: il_aviation_services_law_2012:section_2\n'
                                       'Legal citation: Sefer Ha-Chukkim No. 2360, p. 414 (29 May '
                                       '2012)\n'
                                       'Official source: '
                                       'https://fs.knesset.gov.il/18/law/18_lsr_301013.pdf\n'
                                       'Excerpt:\n'
                                       '## Section 2 - Conditions for entitlement to benefits  \n'
                                       '### 2(a)  \n'
                                       'A passenger who has been issued a flight ticket for a '
                                       'flight in relation to which a qualifying ground exists is '
                                       'entitled to all or some of the benefits if the passenger '
                                       "presented themself on time at the flight operator's "
                                       'check-in counter at the airport or, if no such counter was '
                                       'allocated for that flight, presented themself on time '
                                       'before the person appointed on behalf of the flight '
                                       'operator under section 8C(a1) of the Aviation Services '
                                       'Licensing Law, 5723-1963. A passenger is not required to '
                                       'present themself as stated if the flight was cancelled.  \n'
                                       'For this subsection, **"presented themself on time"** '
                                       'means presenting at the time fixed for that purpose and '
                                       'communicated to the passenger by the flight operator, '
                                       'organizer, or travel-agency service provider, provided '
                                       'that the passenger shall not be required to present more '
                                       'than three hours before the scheduled departure time; if '
                                       'no time was fixed, the passenger must present at least 90 '
                                       'minutes before that departure time.\n'
                                       '\n'
                                       '[S3] Aviation Services Law (Compensation and Assistance '
                                       'for Flight Cancellation or Change in Conditions), '
                                       '5772–2012\n'
                                       'Namespace: rights-il\n'
                                       'Retrieval score: 0.723533\n'
                                       'Selection reason: coverage_recovery:event_entitlement\n'
                                       'Document type: passenger_rights\n'
