                                       'Official source: '
                                       'https://fs.knesset.gov.il/25/law/25_lsr_5694585.pdf\n'
                                       'Excerpt:\n'
                                       '### 2(d) - Carrier that ceased all flights to and from '
                                       'Israel  \n'
                                       'Notwithstanding the Principal Law, from the commencement '
                                       'of this Amendment and for as long as the declaration of a '
                                       'special situation on the home front under the Civil '
                                       'Defense Law, 5711-1951, declared on 7 October 2023 remains '
                                       'in force, the following provisions apply to a flight '
                                       'operator that ceased all its flights from and to Israel '
                                       "and to an organizer in connection with that operator's "
                                       "flights, regarding a passenger's entitlement to a "
                                       'replacement flight ticket because of cancellation under '
                                       'section 6(a)(2) of the Principal Law, unless the Minister '
                                       'of Transport and Road Safety prescribes otherwise by order '
                                       'under section 9A(a)(2) of the Principal Law as enacted by '
                                       'this Amendment:  \n'
                                       '1. The flight operator or organizer shall offer the '
                                       "passenger, at the passenger's choice, a replacement flight "
                                       'ticket departing from a different point of origin or '
                                       'arriving at a different destination from those in the '
                                       'original ticket, under conditions as similar as possible '
                                       'to the conditions of the original ticket and at the '
                                       'earliest possible time, or at a later time coordinated '
                                       'with the passenger, subject to seat availability, all in '
                                       'order to assist the passenger in reaching the original '
                                       'destination stated on the original ticket;\n'
                                       '2. A flight operator or organizer offering a replacement '
                                       'ticket under paragraph (1) shall inform the passenger '
                                       'clearly of the right to choose between reimbursement and '
                                       "that replacement ticket. The passenger's consent to "
                                       'receive such a replacement ticket shall be given in '
                                       'writing.\n'
