                                       'Selection reason: semantic\n'
                                       'Document type: passenger_rights\n'
                                       'Section: 2024 Interpretative Guidelines on Regulations '
                                       '(EC) No 261/2004 and No 2027/97 > 3. EVENTS GIVING RIGHTS '
                                       'UNDER REGULATION (EC) No 261/2004 > 3.2.1. Definition of '
                                       'cancellation\n'
                                       'Provision ID: \n'
                                       'Legal citation: Commission Notice C/2024/5687; CELEX '
                                       '52024XC05687\n'
                                       'Official source: '
                                       'https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=CELEX:52024XC05687\n'
                                       'Excerpt:\n'
                                       '### 3.2.1. Definition of cancellation  \n'
                                       'Article 2, point (l), of Regulation (EC) No 261/2004 '
                                       'defines ‘cancellation’ as the non-operation of a flight '
                                       'that was previously planned and on which at least one '
                                       'place was reserved.  \n'
                                       'Cancellation occurs in principle where the planning of the '
                                       'original flight is abandoned and passengers of this flight '
                                       'join passengers on a flight that was also planned, but '
                                       'independently of the original flight. Article 2, point '
                                       '(l), does not require an express decision of cancellation '
                                       'by the air '
                                       'carrier[(55)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr55-C_202405687EN.000101-E0055).  \n'
                                       'A flight that was carried out between the places of '
                                       'departure and arrival in accordance with the planned '
                                       'schedule but during which an unscheduled stopover took '
                                       'place cannot be regarded as '
                                       'cancelled[(56)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr56-C_202405687EN.000101-E0056).  \n'
                                       'By contrast, the '
                                       'Court[(57)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr57-C_202405687EN.000101-E0057) '
                                       'considers that it cannot, as a rule, be concluded that '
                                       'there is a flight delay or cancellation on the basis of a '
                                       '‘delay’ or a ‘cancellation’ being shown on the airport '
                                       'departures board or announced by the air carrier’s staff. '
                                       'Similarly, the fact that passengers recover their luggage '
                                       'or obtain new boarding cards is not, as a rule, a deciding '
                                       'factor to ascertain that a flight has been cancelled. '
                                       'These circumstances are not connected with the objective '
                                       'characteristics of the flight as such and may arise from '
                                       'different factors. In particular, the Court highlighted '
                                       'that these circumstances (i.e. the announcement of a '
                                       'flight as being ‘delayed’ or ‘cancelled’) can ‘be '
                                       'attributable to inaccurate classifications or to factors '
                                       'obtaining in the airport concerned or, yet again, they may '
                                       'be unavoidable given the waiting time and the fact that it '
                                       'is necessary for the passengers concerned to spend the '
                                       'night in a hotel’.\n'
                                       '\n'
