                                       'Excerpt:\n'
                                       '## First Schedule - Monetary compensation  \n'
                                       'Applicable under section 3(a)(4). These are the amounts '
                                       'stated in the original 2012 enactment; section 13 provides '
                                       'for annual updating.  \n'
                                       '| Flight distance | Amount in the original enactment |\n'
