                                       'Excerpt:\n'
                                       '## Article 5: Reservations  \n'
                                       '**Conditions for reservations**  \n'
                                       '5.1.  \n'
                                       '5.1.1. Each flight coupon will be accepted only for '
                                       'carriage in the Travel Class specified on the coupon and '
                                       'for the day and flight for which there is a seat '
                                       'reservation. For tickets without a seat reservation, a '
                                       'seat may be reserved later if there is still one available '
                                       'on the desired flight.  \n'
                                       '5.1.2. We or one of our Authorized Agents will record your '
                                       'booking(s). We will send you a written passenger receipt '
                                       'on request.  \n'
                                       '5.1.3. Certain fares are subject to conditions that limit '
                                       'your right to rebook or cancel reservations.  \n'
                                       '(5.2. has been deleted.)  \n'
                                       '**Personal data**  \n'
                                       '5.3. We process your personal data according to all the '
                                       'relevant data privacy regulations and only for the '
                                       'following purposes: making flight bookings, purchasing '
                                       'tickets, obtaining additional services,refund and '
                                       'rebooking of tickets and additional services, development '
                                       'and provision of services, facilitating immigration and '
                                       'entry procedures, as well as making information associated '
                                       'with the organization of your journey available to the '
                                       'relevant government agencies and other airlines, or to '
                                       'other providers of the aforementioned services.  \n'
                                       '**Advance seat reservations**  \n'
                                       '5.4.  \n'
                                       '5.4.1. You have the option of making an advance seat '
                                       'reservation on some Lufthansa flights. In the context of '
                                       'this service, you can choose –if available – a specific '
                                       'seating category (aisle, window or middle seat, a seat '
                                       'with more legroom). Some fares are subject to a charge for '
                                       'this service, depending on the type of seat. The price may '
                                       'vary based on the seat category, time and type of booking, '
                                       'flight and route. There is no obligation to make a '
                                       '(chargeable) advance seat reservation.You can find more '
                                       'information on the page about [__ Seat '
                                       'reservations](https://www.lufthansa.com/cn/en/advance-seat-reservation).  \n'
                                       '5.4.2.If you decide not to pay for a seat reservation, you '
                                       'will be allocated a seat free of charge at check-in. '
                                       'Changes to an already selected or allocated seat may incur '
                                       'a charge depending on the selected fare. Whenever you use '
                                       'the “automated check-in” service, at the end of the '
                                       'process you are given the option of selecting a seat other '
                                       'than the one assigned to you. This may incur a fee '
                                       'depending on the fare, providing other seats are still '
                                       'available. However, we cannot guarantee specific seats or '
                                       'the availability of a specific seat category.  \n'
                                       '5.4.3 If you rebook your flight, your existing seat '
                                       'reservation expires and you can proceed with a new seat '
                                       'reservation which may incur higher costs depending on the '
                                       'fare, seat category, time of rebooking and flight route.\n'
                                       '\n'
