                                       '2012)\n'
                                       'Official source: '
                                       'https://fs.knesset.gov.il/18/law/18_lsr_301013.pdf\n'
                                       'Excerpt:\n'
                                       '## Section 6 - Cancelled flight  \n'
                                       '### 6(a)  \n'
                                       'A passenger to whom a ticket was issued for a cancelled '
                                       'flight is entitled to receive the following benefits from '
                                       'the flight operator or organizer:  \n'
                                       '1. Assistance services;\n'
                                       '2. Reimbursement or a replacement flight ticket, at the '
                                       "passenger's choice;\n"
                                       '3. Monetary compensation as specified in the First '
                                       'Schedule.\n'
                                       '\n'
                                       '[S4] Aviation Services Law (Compensation and Assistance '
                                       'for Flight Cancellation or Change in Conditions), '
                                       '5772–2012\n'
