                                       'Section: Aviation Services Law (Compensation and '
                                       'Assistance for Flight Cancellation or Change in '
                                       'Conditions), 5772-2012 > Section 6 - Cancelled flight > '
                                       '6(e)\n'
                                       'Provision ID: il_aviation_services_law_2012:section_6\n'
                                       'Legal citation: Sefer Ha-Chukkim No. 2360, p. 414 (29 May '
                                       '2012)\n'
                                       'Official source: '
                                       'https://fs.knesset.gov.il/18/law/18_lsr_301013.pdf\n'
                                       'Excerpt:\n'
                                       '### 6(e)  \n'
                                       'Without limiting subsection (c), a passenger whose flight '
                                       'was cancelled is not entitled to the monetary compensation '
                                       'specified in the First Schedule if the flight operator or '
                                       'organizer proves that one of the following applies:  \n'
                                       '1. The flight was cancelled because of extraordinary '
                                       'circumstances beyond its control and the cancellation '
                                       'could not have been prevented even if it had done '
                                       'everything within its control;\n'
                                       '2. The flight was cancelled because of a protected strike '
                                       'or protected work-to-rule action;\n'
                                       '3. The flight was cancelled to avoid desecration of the '
                                       'Sabbath or a Jewish holiday.\n'
                                       '\n'
