                                       '[S14] 2024 Interpretative Guidelines on Regulations (EC) '
                                       'No 261/2004 and No 2027/97\n'
                                       'Namespace: rights-eu\n'
                                       'Retrieval score: 0.573271\n'
                                       'Selection reason: semantic\n'
                                       'Document type: passenger_rights\n'
                                       'Section: 2024 Interpretative Guidelines on Regulations '
                                       '(EC) No 261/2004 and No 2027/97 > 4. PASSENGERS’ RIGHTS > '
                                       '4.3.2. Provision of meals, refreshments and accommodation\n'
                                       'Provision ID: \n'
                                       'Legal citation: Commission Notice C/2024/5687; CELEX '
                                       '52024XC05687\n'
                                       'Official source: '
                                       'https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=CELEX:52024XC05687\n'
                                       'Excerpt:\n'
                                       'If passengers reject the air carrier’s reasonable care '
                                       'that has to be offered under Article 9 and make their own '
                                       'arrangements, the air carrier is not obliged to reimburse '
                                       'the expenses incurred by the passenger, unless provided '
                                       'otherwise under national law or agreed beforehand by the '
                                       'air carrier. In order to provide equal treatment between '
                                       'passengers, such reimbursement can never exceed the value '
                                       'of the aforementioned ‘reasonable offer’ of the air '
                                       'carrier. Passengers should also retain all receipts for '
                                       'the expenses incurred.  \n'
                                       'In any event, passengers who feel that they are entitled '
                                       'to have more of their expenses reimbursed or to obtain '
                                       'compensation for damage suffered as a result of a delay, '
                                       'including expenses, retain the right to base their claims '
                                       'on the provisions of the Montreal Convention as well as '
                                       'Article 3 of Regulation (EC) No 2027/97, and to take the '
                                       'air carrier to a national court or address themselves to '
                                       'the competent national enforcement body. In some Member '
                                       'States, passengers may have to turn to entities that '
                                       'provide alternative dispute resolution for consumer '
                                       'disputes (see Section 7.3).  \n'
                                       'Regarding the obligation to offer hotel accommodation free '
                                       'of charge, the Court has clarified that the wording ‘shall '
                                       'be offered free of charge … hotel accommodation’ reflects '
                                       'the desire of the EU legislature to prevent passengers '
                                       'concerned from having to bear the burden of finding a '
                                       'hotel room and of paying the costs of this room '
                                       'themselves, as these passengers must be cared for by the '
                                       'air carrier, which must make the necessary arrangements '
                                       'for this purpose. However, it does not expressly follow '
                                       'from the wording of this provision that beyond the '
                                       'obligation to care for passengers, the EU legislature '
                                       'wished to impose on air carriers the obligation to take '
                                       'care of the accommodation arrangements as '
                                       'such[(90)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr90-C_202405687EN.000101-E0090), '
                                       'for instance by booking a specific room in the name of the '
                                       'passenger.  \n'
                                       'On a similar line, the Court has stated that in the case '
                                       'of an incident at the hotel, the air carrier cannot be '
                                       'required, on the basis of Regulation (EC) No 261/2004 '
                                       'alone, to compensate a passenger for damage caused by '
                                       'fault on the part of employees of the hotel in which the '
                                       'accommodation is '
                                       'provided[(91)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr91-C_202405687EN.000101-E0091).\n'
                                       '\n'
