                                       'Section: Aviation Services Law (Compensation and '
                                       'Assistance for Flight Cancellation or Change in '
                                       'Conditions), 5772-2012 > Section 1 - Definitions\n'
                                       'Provision ID: il_aviation_services_law_2012:section_1\n'
                                       'Legal citation: Sefer Ha-Chukkim No. 2360, p. 414 (29 May '
                                       '2012)\n'
                                       'Official source: '
                                       'https://fs.knesset.gov.il/18/law/18_lsr_301013.pdf\n'
                                       'Excerpt:\n'
                                       '## Section 1 - Definitions  \n'
                                       'In this Law:  \n'
                                       '**"Benefits"** means any of the following: reimbursement, '
                                       'a replacement flight ticket, monetary compensation, and '
                                       'assistance services;  \n'
                                       '**"Reimbursement"** has the meaning assigned to it in '
                                       'section 3(a)(2);  \n'
                                       '**"Tour package"** means a combination of at least two '
                                       'travel-agency services, including the booking or sale of a '
                                       'flight ticket;  \n'
                                       '**"Stopover"** means a stay at an intermediate destination '
                                       'for the purpose of a connecting flight to the final '
                                       'destination;  \n'
                                       '**"Flight"** means a flight departing from or arriving in '
                                       'the territory of the State of Israel, including a flight '
                                       'that includes a stopover;  \n'
                                       '**"Cancelled flight"** means any of the following; '
                                       'however, a change in the flight number alone shall not be '
                                       'regarded as a cancelled flight:  \n'
                                       '1. A flight that did not take place;\n'
                                       '2. A flight that departed at least eight hours after the '
                                       'time stated on the flight ticket, or after such other '
                                       'delay as may be prescribed under section 6(h);  \n'
                                       '**"Final destination"** means the destination stated on '
                                       'the flight ticket for a direct flight or, for a flight '
                                       'that includes a stopover, the last destination stated on '
                                       'the flight ticket;  \n'
                                       '**"Flight ticket"** means a confirmation, issued by a '
                                       'flight operator, organizer, or a person authorized by '
                                       'either of them, of an undertaking to transport a passenger '
                                       'by air, even if the confirmation was issued as part of a '
                                       'tour package; for this purpose, "confirmation" includes an '
                                       'electronic message;  \n'
                                       '**"Replacement flight ticket"** has the meaning assigned '
                                       'to it in section 3(a)(3);  \n'
                                       '**"Organizer"** means a person who charters all or part of '
                                       "an aircraft's capacity for transporting passengers and "
                                       'their baggage for the purpose of selling that capacity to '
                                       'others;  \n'
                                       '**"Flight operator"** means an operator of an aircraft for '
                                       'consideration for the transport of passengers and their '
                                       'baggage from, to, or within the State of Israel;  \n'
                                       '**"Travel-agency service provider"** means a person who '
                                       'provides a travel-agency service for consideration or, '
                                       'although not for consideration, on a regular basis;  \n'
                                       '**"Monetary compensation"** has the meaning assigned to it '
                                       'in section 3(a)(4) or (5), as applicable;  \n'
                                       '**"Qualifying ground"** means a ground that entitles a '
                                       'passenger to receive benefits under sections 5 through '
                                       '9;  \n'
                                       '**"Airports Authority"** means the Airports Authority '
                                       'established under the Airports Authority Law, 5737-1977;\n'
                                       '\n'
                                       '[S2] Aviation Services Law (Compensation and Assistance '
                                       'for Flight Cancellation or Change in Conditions), '
                                       '5772–2012\n'
                                       'Namespace: rights-il\n'
                                       'Retrieval score: 0.623822\n'
                                       'Selection reason: coverage_recovery:eligibility\n'
                                       'Document type: passenger_rights\n'
                                       'Section: Aviation Services Law (Compensation and '
                                       'Assistance for Flight Cancellation or Change in '
                                       'Conditions), 5772-2012 > Section 2 - Conditions for '
                                       'entitlement to benefits > 2(a)\n'
                                       'Provision ID: il_aviation_services_law_2012:section_2\n'
                                       'Legal citation: Sefer Ha-Chukkim No. 2360, p. 414 (29 May '
                                       '2012)\n'
                                       'Official source: '
                                       'https://fs.knesset.gov.il/18/law/18_lsr_301013.pdf\n'
                                       'Excerpt:\n'
                                       '## Section 2 - Conditions for entitlement to benefits  \n'
                                       '### 2(a)  \n'
                                       'A passenger who has been issued a flight ticket for a '
                                       'flight in relation to which a qualifying ground exists is '
                                       'entitled to all or some of the benefits if the passenger '
                                       "presented themself on time at the flight operator's "
                                       'check-in counter at the airport or, if no such counter was '
                                       'allocated for that flight, presented themself on time '
                                       'before the person appointed on behalf of the flight '
                                       'operator under section 8C(a1) of the Aviation Services '
                                       'Licensing Law, 5723-1963. A passenger is not required to '
                                       'present themself as stated if the flight was cancelled.  \n'
                                       'For this subsection, **"presented themself on time"** '
                                       'means presenting at the time fixed for that purpose and '
                                       'communicated to the passenger by the flight operator, '
                                       'organizer, or travel-agency service provider, provided '
                                       'that the passenger shall not be required to present more '
                                       'than three hours before the scheduled departure time; if '
                                       'no time was fixed, the passenger must present at least 90 '
                                       'minutes before that departure time.\n'
                                       '\n'
                                       '[S3] Aviation Services Law (Compensation and Assistance '
                                       'for Flight Cancellation or Change in Conditions), '
                                       '5772–2012\n'
                                       'Namespace: rights-il\n'
                                       'Retrieval score: 0.723533\n'
                                       'Selection reason: coverage_recovery:event_entitlement\n'
