                                       'Excerpt:\n'
                                       '### 1. In case of cancellation of a flight, the passengers '
                                       'concerned shall:  \n'
                                       '(a) be offered assistance by the operating air carrier in '
                                       'accordance with Article 8; and  \n'
                                       '(b) be offered assistance by the operating air carrier in '
                                       'accordance with Article 9(1)(a) and 9(2), as well as, in '
                                       'event of re-routing when the reasonably expected time of '
                                       'departure of the new flight is at least the day after the '
                                       'departure as it was planned for the cancelled flight, the '
                                       'assistance specified in Article 9(1)(b) and 9(1)(c); '
                                       'and  \n'
                                       '(c) have the right to compensation by the operating air '
                                       'carrier in accordance with Article 7, unless:  \n'
                                       '(i) they are informed of the cancellation at least two '
                                       'weeks before the scheduled time of departure; or  \n'
                                       '(ii) they are informed of the cancellation between two '
                                       'weeks and seven days before the scheduled time of '
                                       'departure and are offered re-routing, allowing them to '
                                       'depart no more than two hours before the scheduled time of '
                                       'departure and to reach their final destination less than '
                                       'four hours after the scheduled time of arrival; or  \n'
                                       '(iii) they are informed of the cancellation less than '
                                       'seven days before the scheduled time of departure and are '
                                       'offered re-routing, allowing them to depart no more than '
                                       'one hour before the scheduled time of departure and to '
                                       'reach their final destination less than two hours after '
                                       'the scheduled time of arrival.\n'
