                                       'Official source: '
                                       'https://op.europa.eu/o/opportal-service/download-handler?identifier=439cd3a7-fd3c-4da7-8bf4-b0f60600c1d6&format=PDF&language=en&productionSystem=cellar\n'
                                       'Excerpt:\n'
                                       '### 1. Where reference is made to this Article, passengers '
                                       'shall receive compensation amounting to:  \n'
                                       '(a) EUR 250 for all flights of 1500 kilometres or less;  \n'
                                       '(b) EUR 400 for all intra-Community flights of more than '
                                       '1500 kilometres, and for all other flights between 1500 '
                                       'and 3500 kilometres;  \n'
                                       '(c) EUR 600 for all flights not falling under (a) or '
                                       '(b).  \n'
                                       'In determining the distance, the basis shall be the last '
                                       'destination at which the denial of boarding or '
                                       "cancellation will delay the passenger's arrival after the "
                                       'scheduled time.  \n'
                                       '2. When passengers are offered re-routing to their final '
                                       'destination on an alternative flight pursuant to Article '
                                       '8, the arrival time of which does not exceed the scheduled '
                                       'arrival time of the flight originally booked  \n'
                                       '(a) by two hours, in respect of all flights of 1500 '
                                       'kilometres or less; or  \n'
                                       '(b) by three hours, in respect of all intra-Community '
                                       'flights of more than 1500 kilometres and for all other '
                                       'flights between 1500 and 3500 kilometres; or  \n'
                                       '(c) by four hours, in respect of all flights not falling '
                                       'under (a) or (b),  \n'
                                       'the operating air carrier may reduce the compensation '
                                       'provided for in paragraph 1 by 50 %.  \n'
                                       '3. The compensation referred to in paragraph 1 shall be '
                                       'paid in cash, by electronic bank transfer, bank orders or '
                                       'bank cheques or, with the signed agreement of the '
                                       'passenger, in travel vouchers and/or other services.\n'
