                                       'Excerpt:\n'
                                       '## Section 9A - Changes to passenger benefits because of a '
                                       'special situation  \n'
                                       '### 9A(a) - Ministerial order  \n'
                                       'If a special situation has been declared and the '
                                       'declaration has remained in force for more than 14 days, '
                                       'the Minister, after consulting the Minister of Economy and '
                                       'Industry and with the approval of the Knesset Economic '
                                       'Affairs Committee, may prescribe by order, for a flight '
                                       'whose date stated on the flight ticket falls within a '
                                       'period specified by the Minister (in this section, the '
                                       '**"specified period"**), one or more of the following:  \n'
                                       '1. **Limitation of accommodation services.** The '
                                       'accommodation services to which a passenger is entitled '
                                       'under this Law, other than under section 5, may be limited '
                                       'to a number of nights prescribed by the Minister, which '
                                       'shall not be fewer than two, provided that the Minister is '
                                       'satisfied that the special situation has caused a '
                                       'substantial impairment in the supply of passenger flights '
                                       'from and to Israel;\n'
                                       '2. **Changes concerning replacement flight tickets.** The '
                                       'entitlement to a replacement flight ticket that a flight '
                                       "operator or organizer must offer, at the passenger's "
                                       'choice, because of a cancellation under section 6 may '
                                       'apply subject to changes prescribed by the Minister, in '
                                       'order to assist the passenger in reaching the final '
                                       'destination stated on the original flight ticket, under '
                                       'conditions as similar as possible to those of the original '
                                       'ticket and at a time as close as possible to the time '
                                       'stated on that ticket. Such changes may include '
                                       'entitlement to a ticket departing from a different point '
                                       'of origin or arriving at a different destination from '
                                       'those stated on the original ticket. If the Minister makes '
                                       'an order under this paragraph, the order shall include '
                                       'provisions requiring a flight operator or organizer to '
                                       'inform the passenger clearly of the right to choose '
                                       'between reimbursement and a replacement flight ticket '
                                       'under this paragraph;\n'
                                       '3. One of the following:\n'
                                       '1. **Shorter advance-notice period.** The advance-notice '
                                       'period for cancellation of a flight or for bringing its '
                                       'departure forward by more than eight hours, where the '
                                       'passenger is consequently not entitled to monetary '
                                       'compensation under sections 6(c)(1) and 8(b)(1), may be '
                                       'shorter than 14 days but shall not be shorter than three '
                                       'days, provided that the Minister is satisfied that the '
                                       'special situation has substantially impaired the ability '
                                       'of flight operators or organizers to plan a flight '
                                       'schedule, including their ability to modify the planned '
                                       'schedule;\n'
                                       '\n'
                                       '[S17] 2024 Interpretative Guidelines on Regulations (EC) '
                                       'No 261/2004 and No 2027/97\n'
                                       'Namespace: rights-eu\n'
                                       'Retrieval score: 0.565567\n'
                                       'Selection reason: semantic\n'
                                       'Document type: passenger_rights\n'
                                       'Section: 2024 Interpretative Guidelines on Regulations '
                                       '(EC) No 261/2004 and No 2027/97 > 4. PASSENGERS’ RIGHTS > '
                                       '4.2. Right to reimbursement, re-routing or rebooking in '
                                       'the event of denied boarding or cancellation\n'
                                       'Provision ID: \n'
                                       'Legal citation: Commission Notice C/2024/5687; CELEX '
                                       '52024XC05687\n'
                                       'Official source: '
                                       'https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=CELEX:52024XC05687\n'
                                       'Excerpt:\n'
                                       'If the re-routed flight accepted under Article 8(1), point '
                                       '(b) or (c), is also cancelled or delayed at arrival by at '
                                       'least 3 hours, a new right to compensation under Article 7 '
                                       'arises[(86)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr86-C_202405687EN.000101-E0086). '
                                       'The Commission recommends that options be clearly spelled '
                                       'out to passengers if assistance is to be provided.  \n'
                                       'If a passenger has booked an outbound flight and a return '
                                       'flight separately with different air carriers and the '
                                       'outbound flight is cancelled, reimbursement is due for '
                                       'this flight only. However, in the case of two flights that '
                                       'are part of the same contract but still operated by '
                                       'different air carriers, in addition to their right to '
                                       'compensation from the operating air carrier, passengers '
                                       'should be offered two options in the event of cancellation '
                                       'of the outbound flight:  \n'
                                       'a)to be reimbursed for the whole ticket (i.e. both '
                                       'flights); or  \n'
                                       'b)to be re-routed on another flight for the outbound '
                                       'flight.  \n'
                                       'Lastly, in the very specific setting of the repatriation '
                                       'of stranded passengers during the outbreak of the COVID-19 '
                                       'pandemic, the Court has ruled that a repatriation flight '
                                       'organised by a Member State in the context of consular '
                                       'assistance, following the cancellation of a flight, does '
                                       'not constitute ‘re-routing, under comparable transport '
                                       'conditions, to [the] final destination’, within the '
                                       'meaning of Article 8(1), point (b), of Regulation (EC) No '
                                       '261/2004, which must be offered by the operating air '
                                       'carrier to the passenger whose flight has been cancelled. '
                                       'Thus a passenger who is required to pay a compulsory '
                                       'contribution to the costs incurred by the Member State '
                                       'concerned does not have a right to reimbursement of this '
                                       'contribution at the expense of the operating air carrier '
                                       'on the basis of Regulation (EC) No '
                                       '261/2004[(87)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr87-C_202405687EN.000101-E0087).\n'
                                       '\n'
                                       '[S18] 2024 Interpretative Guidelines on Regulations (EC) '
                                       'No 261/2004 and No 2027/97\n'
                                       'Namespace: rights-eu\n'
                                       'Retrieval score: 0.558453\n'
                                       'Selection reason: semantic\n'
                                       'Document type: passenger_rights\n'
                                       'Section: 2024 Interpretative Guidelines on Regulations '
                                       '(EC) No 261/2004 and No 2027/97 > 4. PASSENGERS’ RIGHTS > '
                                       '4.2. Right to reimbursement, re-routing or rebooking in '
                                       'the event of denied boarding or cancellation\n'
                                       'Provision ID: \n'
                                       'Legal citation: Commission Notice C/2024/5687; CELEX '
                                       '52024XC05687\n'
                                       'Official source: '
                                       'https://eur-lex.europa.eu/legal-content/EN/TXT/PDF/?uri=CELEX:52024XC05687\n'
                                       'Excerpt:\n'
                                       'The air carrier should simultaneously offer the choice '
                                       'between reimbursement and re-routing. In the case of '
                                       'connecting flights, the air carrier should simultaneously '
                                       'offer the choice between reimbursement and a return flight '
                                       'to the airport of departure and re-routing. The air '
                                       'carrier has to bear the costs for re-routing or a return '
                                       'flight. If the air carrier does not comply with its '
                                       'obligation to offer re-routing or return under comparable '
                                       'transport conditions at the earliest opportunity, it must '
                                       'reimburse the costs for an alternative flight to the '
                                       'passenger’s final destination or a return flight incurred '
                                       'by the passenger. The burden of proving that re-routing '
                                       'was performed at the earliest opportunity lies with the '
                                       'operating air '
                                       'carrier[(79)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr79-C_202405687EN.000101-E0079). '
                                       'The same applies to the return flight to the first point '
                                       'of departure. If the air carrier does not offer the choice '
                                       'between reimbursement and re-routing and, in the case of '
                                       'connecting flights, reimbursement and a return flight to '
                                       'the airport of departure and re-routing, but decides '
                                       'unilaterally to reimburse the passenger, the passenger is '
                                       'entitled to a further reimbursement of the price '
                                       'difference with the new ticket under comparable transport '
                                       'conditions.  \n'
                                       'If the booking was made through a third party, such as a '
                                       'booking platform, the onus is on the air carrier, in the '
                                       'event of cancellation of a flight, to offer assistance to '
                                       'the passengers concerned such as offering them '
                                       'reimbursement of the ticket, at the price at which it was '
                                       'bought, and, where necessary, a return flight to the first '
                                       'point of '
                                       'departure[(80)](https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:52024XC05687#ntr80-C_202405687EN.000101-E0080).  \n'
                                       'However, if an air carrier can demonstrate that it has '
                                       'contacted the passengers who have accepted to give their '
                                       'personal contact details, and that it has sought to '
                                       'provide the assistance required by Article 8, but the '
                                       'passengers have nonetheless made their own assistance or '
                                       're-routing arrangements, then the air carrier may conclude '
                                       'that it is not responsible for any additional costs the '
                                       'passengers have incurred and may decide not to reimburse '
                                       'them.\n'
