                                       'Excerpt:\n'
                                       '3.3.4 The following applies to the carriage of passengers '
                                       'who have their habitual residence in Germany or whose '
                                       'place of departure or destination is in Germany as shown '
                                       'in the booking:  \n'
                                       'If you have chosen a fare that requires observance of a '
                                       'fixed ticket sequence and carriage is not used on all legs '
                                       ', we will subsequently collect any fare difference for '
                                       'your altered routing, in accordance with Article 3.3.3. '
                                       'This does not apply if you are prevented, due to force '
                                       'majeure, illness or any other reasons which arise only '
                                       'after booking and which require or make reasonable a '
                                       'deviation from the sequence of the ticket, from commencing '
                                       'carriage on all legs or in the sequence specified on the '
                                       'ticket. You are then obliged to inform us of these reasons '
                                       'immediately as soon as you become aware of them and to '
                                       'prove that at the time of booking you intended to take '
                                       'carriage on all legs or in the sequence specified on the '
                                       'ticket, and that the use of any individual legs is based '
                                       'on circumstances which have arisen only after the booking '
                                       'and which require or make reasonable a deviation from the '
                                       'sequence of the ticket. The fastest way to reach us is via '
                                       'the [__ '
                                       'form](https://www.lufthansa.com/de/en/modified-coupon-sequence)provided '
                                       'for this purpose. If you are unable to provide proof prior '
                                       'to the start of the carriage, you will be required to pay '
                                       'any difference to the higher fare determined in accordance '
                                       'with Article 3.3.3 prior to departure. If we do not '
                                       'receive payment, we will charge you the difference after '
                                       'carriage. For this purpose, you must provide us with your '
                                       'address before departure and verify its accuracy (e.g. by '
                                       'presenting an official ID) so that we can claim the '
                                       'difference afterwards. Please note that we may make '
                                       'carriage dependent on a) receipt of payment in the amount '
                                       'of the difference prior to departure or b) whether you '
                                       'have provided us with your address prior to departure and '
                                       'verified its accuracy. The difference will not be '
                                       'calculated retrospectively if you provide proof of the '
                                       'reasons for the changes in the sequence of the ticket '
                                       'immediately after carriage. In this case, we will also '
                                       'refund any additional payment of the difference that has '
                                       'already been made. To provide proof, the fastest way to '
                                       'reach us is via the [__ '
                                       'form](https://www.lufthansa.com/de/en/modified-coupon-sequence) '
                                       'provided for this purpose.  \n'
                                       '3.3.5 The following applies to the carriage of passengers '
