                                       'Section: Aviation Services Law (Compensation and '
                                       'Assistance for Flight Cancellation or Change in '
                                       'Conditions), 5772-2012 > Section 3 - Types of benefits > '
                                       '3(a)\n'
                                       'Provision ID: il_aviation_services_law_2012:section_3\n'
                                       'Legal citation: Sefer Ha-Chukkim No. 2360, p. 414 (29 May '
                                       '2012)\n'
                                       'Official source: '
                                       'https://fs.knesset.gov.il/18/law/18_lsr_301013.pdf\n'
                                       'Excerpt:\n'
                                       '## Section 3 - Types of benefits  \n'
                                       '### 3(a)  \n'
                                       'The benefits under this Law are:  \n'
                                       '1. **Assistance services**, free of charge, as follows:\n'
                                       '1. Food and beverages appropriate to the waiting time (in '
                                       'this Law, **"food and beverages"**);\n'
                                       '2. Hotel accommodation if an overnight stay of one or more '
                                       'nights is required, or if a stay longer than the passenger '
                                       'had planned is required (in this Law, **"accommodation '
                                       'services"**);\n'
                                       '3. Transport between the airport and the hotel in which '
                                       'the passenger is staying as described in subparagraph (2), '
                                       'or, if the passenger chooses to stay at another place '
                                       'within a reasonable distance of the airport during that '
                                       'period, transport between that place and the airport (in '
                                       'this Law, **"transport services"**);\n'
                                       '4. Two telephone calls and the transmission of a message '
                                       "by fax or email, at the passenger's choice (in this Law, "
                                       '**"communication services"**);\n'
                                       '2. **Reimbursement** of the amount paid for the flight '
                                       'ticket, including every payment made for the ticket, '
                                       'including fees, levies, taxes, and other mandatory '
                                       'payments, all subject to subsection (b). The flight '
                                       'operator or organizer shall reimburse the passenger within '
                                       '21 days after the passenger, or the travel-agency service '
                                       'provider described in section 15, as applicable, applies '
                                       'to it in writing;\n'
                                       "3. **A replacement flight ticket** to the passenger's "
                                       'final destination under conditions as similar as possible '
                                       'to those of the original flight ticket and at the earliest '
                                       'possible time, or at a later time coordinated with the '
                                       'passenger, subject to seat availability;\n'
                                       '4. **Monetary compensation** in the amount specified in '
                                       'the First Schedule. The flight operator or organizer shall '
                                       'pay the compensation within 45 days after the passenger, '
                                       'or the travel-agency service provider described in section '
                                       '15, as applicable, applies to it in writing. Compensation '
                                       'shall be paid in cash, by bank transfer, or by check or, '
                                       'if the passenger expressly agrees in writing, by travel '
                                       'vouchers or another agreed means of payment;\n'
                                       '5. **Monetary compensation for a change in the conditions '
                                       'of the flight ticket**, as specified in the Second '
                                       'Schedule. The flight operator or organizer shall pay the '
                                       'compensation within 21 days after the flight, in cash, by '
                                       'bank transfer, or by check or, if the passenger expressly '
                                       'agrees in writing, by travel vouchers or another agreed '
                                       'means of payment.\n'
